async function reportsPage(){const from=new Date(Date.now()-29*86400000).toISOString().slice(0,10),to=new Date().toISOString().slice(0,10),root=$("#gymContent");root.innerHTML=hero("Gym Reports","Filter membership, attendance, payment and utilization summaries.")+`<section class="gym-card mt-3"><form id="reportForm" class="gym-toolbar"><div><label>From</label><input id="reportFrom" type="date" class="form-control" value="${from}"></div><div><label>To</label><input id="reportTo" type="date" class="form-control" value="${to}"></div><button class="gym-btn gym-btn-primary align-self-end" type="submit">Run report</button></form><div id="reportOutput"></div></section>`;const run=async()=>{const[summary,filtered]=await Promise.all([apiGet("/api/v1/gym/reports/summary"),apiGet(`/api/v1/gym/reports/filtered?from=${$("#reportFrom").value}&to=${$("#reportTo").value}`)]);$("#reportOutput").innerHTML=`<div class="gym-grid gym-kpis">${kpi("Members",summary.members||0,"Registered")}${kpi("Active memberships",summary.activeMemberships||0,"Current")}${kpi("Expiring soon",summary.expiringSoon||0,"30 days")}${kpi("Payments",money(filtered.payments||0),"Selected period")}${kpi("Payment count",filtered.paymentCount||0,"Selected period")}${kpi("Check-ins",filtered.checkIns||0,"Selected period")}</div>`};$("#reportForm").onsubmit=async e=>{e.preventDefault();try{await run()}catch(x){showError(x)}};await run()}
